-- Initial CodePet AI schema. Generated from prisma/schema.prisma.
CREATE TABLE `User` (`id` VARCHAR(191) NOT NULL, `email` VARCHAR(191) NOT NULL, `passwordHash` VARCHAR(191) NOT NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, UNIQUE INDEX `User_email_key`(`email`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `Pet` (`id` VARCHAR(191) NOT NULL, `userId` VARCHAR(191) NOT NULL, `name` VARCHAR(191) NOT NULL, `species` ENUM('DOG','CAT','PANDA','FOX','ROBOT') NOT NULL, `level` INTEGER NOT NULL DEFAULT 1, `experience` INTEGER NOT NULL DEFAULT 0, `selected` BOOLEAN NOT NULL DEFAULT false, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, INDEX `Pet_userId_idx`(`userId`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `PetCustomization` (`id` VARCHAR(191) NOT NULL, `petId` VARCHAR(191) NOT NULL, `color` VARCHAR(191) NOT NULL DEFAULT 'default', `accessory` VARCHAR(191) NULL, `personality` VARCHAR(191) NOT NULL DEFAULT 'FRIENDLY_MENTOR', `soundsEnabled` BOOLEAN NOT NULL DEFAULT true, `voiceEnabled` BOOLEAN NOT NULL DEFAULT false, UNIQUE INDEX `PetCustomization_petId_key`(`petId`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `CodingSession` (`id` VARCHAR(191) NOT NULL, `userId` VARCHAR(191) NOT NULL, `language` VARCHAR(191) NOT NULL, `startedAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `endedAt` DATETIME(3) NULL, INDEX `CodingSession_userId_startedAt_idx`(`userId`,`startedAt`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `DebugSession` (`id` VARCHAR(191) NOT NULL, `codingSessionId` VARCHAR(191) NOT NULL, `mode` ENUM('MANUAL','SUGGESTION','AUTO') NOT NULL DEFAULT 'SUGGESTION', `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `DebugDiagnostic` (`id` VARCHAR(191) NOT NULL, `debugSessionId` VARCHAR(191) NOT NULL, `severity` ENUM('ERROR','WARNING','INFORMATION') NOT NULL, `category` VARCHAR(191) NOT NULL, `message` VARCHAR(191) NOT NULL, `fileName` VARCHAR(191) NOT NULL, `line` INTEGER NOT NULL, `column` INTEGER NOT NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), INDEX `DebugDiagnostic_debugSessionId_severity_idx`(`debugSessionId`,`severity`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `CodeCorrection` (`id` VARCHAR(191) NOT NULL, `debugSessionId` VARCHAR(191) NOT NULL, `originalSnippet` VARCHAR(191) NOT NULL, `correctedSnippet` VARCHAR(191) NOT NULL, `confidence` DOUBLE NOT NULL, `acceptedAt` DATETIME(3) NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `LearningTopic` (`id` VARCHAR(191) NOT NULL, `slug` VARCHAR(191) NOT NULL, `title` VARCHAR(191) NOT NULL, UNIQUE INDEX `LearningTopic_slug_key`(`slug`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `Exercise` (`id` VARCHAR(191) NOT NULL, `topicId` VARCHAR(191) NOT NULL, `title` VARCHAR(191) NOT NULL, `prompt` VARCHAR(191) NOT NULL, PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `ExerciseSubmission` (`id` VARCHAR(191) NOT NULL, `userId` VARCHAR(191) NOT NULL, `exerciseId` VARCHAR(191) NOT NULL, `sourceCode` VARCHAR(191) NULL, `passed` BOOLEAN NOT NULL, `submittedAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), INDEX `ExerciseSubmission_userId_submittedAt_idx`(`userId`,`submittedAt`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `LearningProgress` (`id` VARCHAR(191) NOT NULL, `userId` VARCHAR(191) NOT NULL, `topicId` VARCHAR(191) NOT NULL, `score` DOUBLE NOT NULL DEFAULT 0, `completedAt` DATETIME(3) NULL, UNIQUE INDEX `LearningProgress_userId_topicId_key`(`userId`,`topicId`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `Achievement` (`id` VARCHAR(191) NOT NULL, `key` VARCHAR(191) NOT NULL, `title` VARCHAR(191) NOT NULL, `description` VARCHAR(191) NOT NULL, UNIQUE INDEX `Achievement_key_key`(`key`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `UserSettings` (`id` VARCHAR(191) NOT NULL, `userId` VARCHAR(191) NOT NULL, `codeHistoryEnabled` BOOLEAN NOT NULL DEFAULT false, `debugMode` ENUM('MANUAL','SUGGESTION','AUTO') NOT NULL DEFAULT 'SUGGESTION', UNIQUE INDEX `UserSettings_userId_key`(`userId`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
